def enhance_home(html):
 html=html.replace('Videovigilancia, control de acceso e intrusión. Diseñados en conjunto para proteger lo que construiste, con atención a cada detalle.','Seguridad electrónica para residencias, empresas y desarrollos en todo Uruguay. Videovigilancia, accesos y protección perimetral, diseñados en conjunto para tu espacio.')
 html=html.replace('El mismo compromiso.<br> Distintas realidades.','Residencias. Empresas.<br> Cada espacio, su proyecto.')
 html=html.replace('La seguridad cambia con el espacio. El criterio para diseñarla también.','De una residencia a una instalación industrial. Explorá cómo cambia el diseño según el lugar, sus usuarios y lo que necesitás proteger.')
 html=html.replace('<a class="text-link" href="#contacto">Conversar sobre mi espacio <span aria-hidden="true">↗</span></a>','<a class="text-link" id="sector-detail" href="/sectores/empresas/">Ver soluciones para empresas <span aria-hidden="true">↗</span></a>')
 directory='<nav class="segment-directory" aria-label="Explorar todos los sectores">'+''.join(f'<a href="/sectores/{s["slug"]}/"><span>{s["name"]}</span><span aria-hidden="true">↗</span></a>' for s in SEGMENTS)+'</nav>'
 marker='</section><section class="section" id="metodo">'
 pro='''<section class="professional-section" id="profesionales"><div class="wrap professional-layout"><div><span class="eyebrow">Arquitectura / Desarrollo / Administración</span><h2>La seguridad también<br> se proyecta desde el plano.</h2></div><div><p>Si sos arquitecto, desarrollador o administrador, podemos coordinar el alcance técnico desde el inicio: accesos, ubicaciones, canalizaciones e infraestructura. Para obras nuevas y propiedades en uso.</p><a class="text-link" href="/profesionales/">Trabajemos sobre tu proyecto <span aria-hidden="true">↗</span></a></div></div></section>'''
 html=html.replace(marker,'</section>'+pro+'<section class="section" id="metodo">')
 # The directory belongs within the existing sector wrap, after the tab panel.
 html=html.replace('</div></div></div></section><section class="professional-section"','</div></div>'+directory+'</div></section><section class="professional-section"',1)
 html=html.replace('placeholder="Nombre de la organización"','placeholder="Empresa, residencia o desarrollo"')
 fields='''<label>Tipo de espacio<select name="segment" required><option value="">Seleccioná el entorno</option><option value="residencias">Residencia</option><option value="empresas">Empresa u oficina</option><option value="edificios">Edificio o desarrollo</option><option value="industria-y-logistica">Industria o logística</option><option value="profesionales">Proyecto de arquitectura o administración</option></select></label><label>Etapa del proyecto<select name="stage" required><option value="">Seleccioná una etapa</option><option>Obra nueva o en planificación</option><option>Propiedad en uso</option><option>Ampliación o renovación de un sistema</option></select></label>'''
 html=html.replace('<label class="full">¿Qué necesitás resolver?',fields+'<label class="full">¿Qué necesitás resolver?')
 html=html.replace('<option value="">Seleccioná una solución</option>Proyecto integral de seguridad</option>','<option value="">Seleccioná una solución</option><option>Proyecto integral de seguridad</option>')
 return html

def create_pages(root,origin,head,header,footer,services):
 paths=[]
 for segment in SEGMENTS:
  slug=segment['slug'];path=f'/sectores/{slug}/';paths.append(path)
  breadcrumb=f'<a href="/">Inicio</a> / <a href="/#sectores">Sectores</a> / {segment["name"]}'
  body=head(segment['title']+' | Liconex',segment['intro'],path)+header
  body+=f'''<main id="main"><section class="inner-hero"><div class="wrap"><p class="breadcrumb">{breadcrumb}</p><span class="eyebrow">Seguridad para {segment['name']} / Uruguay</span><h1>{segment['headline']}</h1><p>{segment['intro']}</p><a class="btn" href="/?segment={slug}#contacto">Evaluar mi proyecto <span aria-hidden="true">↗</span></a></div></section><div class="wrap segment-visual"><img src="/assets/{segment['image']}" alt="{segment['alt']}" width="1600" height="1000"><p>Imagen ilustrativa del tipo de entorno.</p></div><section class="section"><div class="wrap"><div class="section-head"><div><span class="eyebrow">Criterios de diseño</span><h2>Lo que define<br> una buena solución.</h2></div><p>{segment['scenarios']}</p></div><div class="priority-grid">'''
  for i,(title,text) in enumerate(segment['priorities']):body+=f'<div class="priority"><span class="eyebrow">0{i+1}</span><h3>{title}</h3><p>{text}</p></div>'
  body+=f'''</div></div></section><section class="planning"><div class="wrap professional-layout"><div><span class="eyebrow">Antes de instalar</span><h2>Anticipar decisiones.<br> Cuidar el resultado.</h2></div><div><p>{segment['planning']}</p><a class="text-link" href="/profesionales/">Coordinar con el equipo del proyecto ↗</a></div></div></section><section class="section"><div class="wrap"><span class="eyebrow">Soluciones relacionadas</span><div class="related-solutions">'''
  for solution in segment['solutions']:
   svc=next(s for s in services if s[0]==solution);body+=f'<a href="/soluciones/{solution}/">{svc[1]} <span aria-hidden="true">↗</span></a>'
  body+=f'''</div></div></section><section class="contact"><div class="wrap contact-grid"><div><span class="eyebrow">{segment['name']} / Todo Uruguay</span><h2>Empecemos por<br> conocer tu proyecto.</h2><p class="segment-contact-copy">Coordinamos la evaluación y la logística según la ubicación. La propuesta se define a partir del espacio, la infraestructura y las prioridades de uso.</p><a class="btn" href="/?segment={slug}#contacto">Conversar con Liconex ↗</a></div><div class="brief-list"><h3>Para una primera conversación</h3><ul>'''+''.join(f'<li>{q}</li>' for q in segment['questions'])+'</ul></div></div></section><nav class="wrap segment-directory" aria-label="Otros entornos">'+''.join(f'<a href="/sectores/{s["slug"]}/">{s["name"]} ↗</a>' for s in SEGMENTS if s['slug']!=slug)+'</nav></main>'+footer
  structured={'@context':'https://schema.org','@type':'Service','name':segment['title'],'description':segment['intro'],'url':origin+path,'areaServed':{'@type':'Country','name':'Uruguay'},'provider':{'@type':'Organization','name':'Liconex','url':origin}}
  body=body.replace('</head>','<script type="application/ld+json">'+json.dumps(structured,ensure_ascii=False)+'</script></head>')
  dest=root/path.strip('/');dest.mkdir(parents=True,exist_ok=True);(dest/'index.html').write_text(body,encoding='utf-8')
 path='/profesionales/';paths.append(path)
 body=head('Seguridad electrónica para arquitectos y desarrolladores | Liconex Uruguay','Coordinación de seguridad electrónica para obras, desarrollos y administraciones en Uruguay. Accesos, cámaras, canalizaciones e infraestructura desde el proyecto.',path)+header+'''<main id="main"><section class="inner-hero"><div class="wrap"><p class="breadcrumb"><a href="/">Inicio</a> / Profesionales</p><span class="eyebrow">Arquitectos / Desarrolladores / Administradores</span><h1>Integrar la seguridad.<br> Desde las primeras decisiones.</h1><p>Una ubicación, una canalización o un acceso definidos a tiempo pueden evitar intervenciones posteriores. Coordinamos el alcance de seguridad electrónica con las necesidades del proyecto y de sus futuros usuarios.</p><a class="btn" href="/?segment=profesionales#contacto">Conversar sobre una obra o propiedad ↗</a></div></section><article class="article"><h2>Para arquitectos y equipos de obra</h2><p>Revisamos planos e información disponible para acordar ubicaciones de cámaras, lectores, equipos de videoportería y puntos de detección. Coordinamos recorridos de canalización, necesidades de alimentación y espacios técnicos con el equipo responsable.</p><p>El objetivo es integrar la instalación con las terminaciones, la circulación y la arquitectura. Los componentes y sus condiciones de montaje se definen antes de ejecutar.</p><h2>Para desarrolladores inmobiliarios</h2><p>Ayudamos a definir qué debe resolver la seguridad del desarrollo: accesos de residentes y visitas, ingresos vehiculares, espacios comunes y administración posterior. El alcance técnico permite evaluar decisiones y organizar etapas de ejecución.</p><h2>Para administradores de propiedades</h2><p>Evaluamos instalaciones existentes, prioridades de renovación y criterios de gestión. La propuesta contempla quién administra credenciales, quién consulta eventos y cómo se entrega el sistema a quienes lo van a operar.</p><h2>Qué podemos definir en conjunto</h2><ul><li>Objetivos de cobertura y puntos de control.</li><li>Ubicación de equipos, canalizaciones y necesidades de red.</li><li>Compatibilidad con infraestructura existente y etapas de ejecución.</li><li>Criterios de pruebas, entrega de uso y alcance del mantenimiento.</li></ul><h2>Una primera conversación con información concreta</h2><p>Contanos el tipo de proyecto, su ubicación y etapa. Si hay planos o un relevamiento disponible, podemos coordinar cómo compartirlos por un canal directo.</p><a class="btn" href="/?segment=profesionales#contacto">Coordinar una conversación técnica ↗</a><h2>Explorá el tipo de propiedad</h2><div class="related-solutions">'''+''.join(f'<a href="/sectores/{s["slug"]}/">{s["name"]} ↗</a>' for s in SEGMENTS)+'</div></article></main>'+footer
 dest=root/'profesionales';dest.mkdir(exist_ok=True);(dest/'index.html').write_text(body,encoding='utf-8')
 return paths
